    assert 1 <= T <= 1024
    assert args.dtype in {"float32", "float16", "bfloat16"}
    assert args.model in {"gpt2", "gpt2-medium", "gpt2-large", "gpt2-xl", "d12", "d24", "d36", "d48"}
    assert args.opt_type in {"adamw", "signum", "sfadam", "mars", "prodigy", "ademamix", "soap", "mars", "muon"}
